"""
figma_tokens.py
turns the figma variables (pulled with the figma mcp get_variable_defs tool)
into css custom properties, so the web page uses the exact same colors, type
and spacing as the open skill 1 figma dashboards instead of retyped hex codes.

run: python scripts/figma_tokens.py   (writes css/tokens.css)
"""
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
variables = json.loads((root / "scripts" / "figma-variables.json").read_text(encoding="utf-8"))["variables"]

lines = [
    "/* generated by scripts/figma_tokens.py from scripts/figma-variables.json.",
    "   source: the open skill 1 figma file's variables. edit the figma file, not this file. */",
    ":root {",
]
for name, value in variables.items():
    # figma stores sizes as bare numbers, css needs px
    if name.startswith(("font-size", "font-line-height", "space", "radius")):
        value = f"{value}px"
    # inter is the figma font; the fallbacks keep the page readable if google fonts is slow
    if name == "font-family":
        value = '"Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif'
    lines.append(f"  --{name}: {value};")
lines.append("}")

out = root / "css" / "tokens.css"
out.write_text("\n".join(lines) + "\n", encoding="utf-8")
print(f"wrote {out.relative_to(root)} with {len(variables)} tokens")
